export PATH=/workspace/.openart/runners/target/state/service_tools/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin; python -c "import json, os, pathlib; instruction = pathlib.Path(r'/task/instructions/target.md').read_text(encoding='utf-8').strip(); cfg = pathlib.Path(os.environ['XDG_CONFIG_HOME']) / 'opencode' / 'opencode.json'; skills = pathlib.Path(os.environ['OPENART_SKILLS_FILE']); tools = pathlib.Path(os.environ['OPENART_TOOLS_FILE']); mcp = pathlib.Path(os.environ['OPENART_MCP_FILE']); payload = {'role':'target','instruction':instruction,'framework_config_path':str(cfg),'framework_config_exists':cfg.exists(),'skills_file_exists':skills.exists(),'tools_file_exists':tools.exists(),'mcp_file_exists':mcp.exists(),'skills':json.loads(skills.read_text(encoding='utf-8')) if skills.exists() else [],'tools':json.loads(tools.read_text(encoding='utf-8')) if tools.exists() else [],'mcp_servers':json.loads(mcp.read_text(encoding='utf-8')) if mcp.exists() else []}; print(json.dumps(payload, ensure_ascii=False))"
